import type { FileType, Project } from '../plugins'

export function getFileType(filePath: string, project: Project): FileType {
    return filePath.endsWith('.now.ts')
        ? 'fluent'
        : (filePath.endsWith('.ts') || filePath.endsWith('.js')) && project.isInServerDir(filePath)
          ? 'module'
          : filePath.endsWith('.json') || filePath.endsWith('.jsonc')
            ? 'json'
            : 'unknown'
}
